\n    min-height: 100dvh;\n}\n.gp-app.riel-plegado { grid-template-columns: var(--gp-riel-plegado) minmax(0, 1fr); }\n\n.gp-contenido { min-width: 0; padding: clamp(1.1rem, 2vw, 2rem) var(--gp-margen) 3rem; }\n\n/* ---------- Riel ---------- */\n.gp-riel {\n    position: sticky;\n    top: 0;\n    z-index: 30;\n    display: flex;\n    flex-direction: column;\n    height: 100dvh;\n    background: var(--gp-fondo-2);\n    border-right: 1px solid var(--gp-linea);\n}\n/* La franja de tres colores del logo: la marca está siempre presente */\n.gp-riel::before { content: ''; flex-shrink: 0; height: 3px; background: var(--gp-franja); }\n\n.gp-riel-marca {\n    display: flex;\n    align-items: center;\n    gap: .6rem;\n    padding: 1rem 1rem .75rem;\n    font-family: var(--gp-fuente-titulo);\n    font-size: 1.2rem;\n    font-weight: 750;\n    letter-spacing: -.02em;\n}\n.gp-riel-marca img { flex-shrink: 0; width: 2.7rem; height: 2.7rem; }\n.gp-riel-nombre { display: block; line-height: 1.1; }\n.gp-riel-nombre b { display: block; font-weight: 750; }\n.gp-riel-nombre small { display: block; margin-top: .1rem; font-family: var(--gp-fuente); font-size: .66rem; font-weight: 400; letter-spacing: 0; color: var(--gp-texto-2); }\n\n.gp-buscar {\n    display: flex;\n    align-items: center;\n    gap: .55rem;\n    margin: 0 .75rem .6rem;\n    padding: .5rem .6rem;\n    font-size: .86rem;\n    color: var(--gp-texto-3);\n    background: var(--gp-superficie);\n    border: 1px solid var(--gp-linea);\n    border-radius: var(--gp-radio);\n    transition: border-color .15s, color .15s;\n}\n.gp-buscar:hover { color: var(--gp-texto); border-color: var(--gp-linea-fuerte); }\n.gp-buscar span { flex: 1; text-align: left; }\nkbd {\n    padding: .05rem .35rem;\n    font-family: var(--gp-fuente-datos);\n    font-size: .64rem;\n    color: var(--gp-texto-3);\n    background: var(--gp-fondo);\n    border: 1px solid var(--gp-linea);\n    border-radius: 3px;\n}\n\n.gp-nav { flex: 1; min-height: 0; overflow-y: auto; padding: .15rem .75rem .75rem; }\n.gp-nav-grupo { margin-top: .85rem; }\n.gp-nav-grupo:first-child { margin-top: .25rem; }\n.gp-nav-titulo { padding: 0 .55rem .3rem; white-space: nowrap; }\n\n.gp-enlace {\n    position: relative;\n    display: flex;\n    align-items: center;\n    gap: .65rem;\n    padding: .42rem .55rem;\n    font-size: .9rem;\n    font-weight: 500;\n    white-space: nowrap;\n    color: var(--gp-texto-2);\n    text-decoration: none;\n    border-radius: var(--gp-radio);\n    transition: background .12s, color .12s;\n}\n.gp-enlace svg { flex-shrink: 0; color: var(--gp-texto-2); transition: color .12s; }\n.gp-enlace:hover { color: var(--gp-texto); background: var(--gp-superficie); }\n.gp-enlace:hover svg { color: var(--gp-texto-2); }\n.gp-enlace.activo { color: #fff; background: linear-gradient(90deg, #0180A1, #016F8C); font-weight: 650; box-shadow: 0 6px 16px -8px var(--gp-azul); }\n.gp-enlace.activo svg { color: #fff; }\n\n.gp-riel-pie { padding: .55rem .75rem .75rem; border-top: 1px solid var(--gp-linea); }\n.gp-enlace-sala { color: var(--gp-verde-texto); }\n.gp-enlace-sala svg { color: var(--gp-verde-texto); }\n.gp-enlace-sala:hover { color: var(--gp-verde-texto); background: var(--gp-verde-suave); }\n.gp-enlace-sala:hover svg { color: var(--gp-verde-texto); }\n\n.gp-usuario { display: flex; align-items: center; gap: .55rem; padding: .5rem .35rem 0; }\n.gp-avatar {\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    width: 2rem;\n    height: 2rem;\n    font-family: var(--gp-fuente-datos);\n    font-size: .72rem;\n    font-weight: 700;\n    color: var(--gp-azul-texto);\n    background: var(--gp-azul-suave);\n    border-radius: 50%;\n}\n.gp-usuario-datos { flex: 1; min-width: 0; line-height: 1.25; }\n.gp-usuario-datos strong, .gp-usuario-datos span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.gp-usuario-datos strong { font-size: .84rem; font-weight: 600; }\n.gp-usuario-datos span {