rior {\n        position: fixed;\n        right: 0;\n        bottom: 0;\n        left: 0;\n        z-index: 30;\n        display: grid;\n        grid-template-columns: repeat(4, 1fr);\n        height: calc(var(--gp-barra-inferior) + env(safe-area-inset-bottom));\n        padding-bottom: env(safe-area-inset-bottom);\n        background: rgba(15, 27, 23, .96);\n        border-top: 1px solid var(--gp-linea);\n        backdrop-filter: blur(10px);\n    }\n    .gp-barra-inferior a, .gp-barra-inferior button {\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        gap: .2rem;\n        font-size: .68rem;\n        font-weight: 600;\n        color: var(--gp-texto-3);\n        text-decoration: none;\n        background: none;\n        border: 0;\n    }\n    .gp-barra-inferior svg { font-size: 1.1rem; }\n    .gp-barra-inferior .activo { color: var(--gp-azul-texto); }\n\n    .gp-paleta-fondo { padding: .75rem !important; }\n}\n\n/* Hoja inferior con todas las secciones */\n.gp-hoja-fondo {\n    position: fixed;\n    inset: 0;\n    z-index: 60;\n    display: flex;\n    align-items: flex-end;\n    background: rgba(4, 9, 7, .65);\n    animation: gp-aparecer .15s ease-out;\n}\n.gp-hoja {\n    width: 100%;\n    max-height: 85dvh;\n    overflow-y: auto;\n    padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom));\n    background: var(--gp-fondo-2);\n    border-top: 1px solid var(--gp-linea-fuerte);\n    border-radius: 14px 14px 0 0;\n    animation: gp-subir .2s cubic-bezier(.2, .8, .2, 1);\n}\n.gp-hoja-cabecera { display: flex; align-items: center; gap: .6rem; margin-bottom: .5rem; }\n.gp-hoja .gp-enlace { padding-block: .6rem; }\n.gp-hoja-pie { display: grid; grid-template-columns: 1fr 1fr; gap: .5rem; margin-top: 1rem; }\n\n/* ---------- Buscador Ctrl+K ---------- */\n.gp-paleta-fondo {\n    position: fixed;\n    inset: 0;\n    z-index: 70;\n    display: flex;\n    justify-content: center;\n    align-ite